begin;
select plan(12);
create temp table workspace_fixture(actor uuid, other_actor uuid, first_agency uuid, second_agency uuid);
insert into workspace_fixture values(gen_random_uuid(),gen_random_uuid(),null,null);
insert into auth.users(id,email) select actor,actor::text || '@example.invalid' from workspace_fixture union all select other_actor,other_actor::text || '@example.invalid' from workspace_fixture;
select ok(not has_function_privilege('anon','public.onboard_agency(text,text,text,character,text,text,text)','EXECUTE'),'anonymous callers cannot create workspaces');
select set_config('request.jwt.claim.sub',(select actor::text from workspace_fixture),true);
update workspace_fixture set first_agency = public.onboard_agency('First Agency',actor::text,'fixture@example.invalid','NG','Africa/Lagos','Original Name');
select ok((select first_agency is not null from workspace_fixture),'first workspace is created');
update workspace_fixture set second_agency = public.onboard_agency('Second Agency',other_actor::text,'fixture@example.invalid','NG','Africa/Lagos','Changed Name');
select isnt((select first_agency from workspace_fixture),(select second_agency from workspace_fixture),'one person can own two distinct workspaces');
select is((select count(*) from public.agency_memberships where user_id=(select actor from workspace_fixture) and role='owner' and status='active'),2::bigint,'each workspace has an active owner');
select is((select full_name from public.user_profiles where id=(select actor from workspace_fixture)),'Original Name','creating another workspace does not overwrite the profile');
select is(public.onboard_agency('Retry Name',(select other_actor::text from workspace_fixture),'changed@example.invalid','NG','Africa/Lagos','Other Name'),(select second_agency from workspace_fixture),'retry returns the same owned workspace');
select is((select name from public.agencies where id=(select second_agency from workspace_fixture)),'Second Agency','retry does not overwrite workspace details');
select is((select count(*) from public.workflow_templates where agency_id in (select first_agency from workspace_fixture union all select second_agency from workspace_fixture)),4::bigint,'templates are seeded exactly once per workspace');
select is((select count(*) from public.activity_events where actor_user_id=(select actor from workspace_fixture) and event_type='agency.created'),2::bigint,'creation is audited once per workspace');
select set_config('request.jwt.claim.sub',(select other_actor::text from workspace_fixture),true);
select throws_ok($$select public.onboard_agency('Hijack',(select actor::text from workspace_fixture),'fixture@example.invalid','NG','Africa/Lagos','Other User')$$,'23505','workspace_slug_unavailable','another person cannot claim the same slug');
select set_config('request.jwt.claim.sub',(select actor::text from workspace_fixture),true);
update public.agency_memberships set status='revoked' where agency_id=(select second_agency from workspace_fixture);
select throws_ok($$select public.onboard_agency('Revoked',(select other_actor::text from workspace_fixture),'fixture@example.invalid','NG','Africa/Lagos','Original Name')$$,'23505','workspace_slug_unavailable','revoked owners cannot reuse a workspace');
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.onboard_agency('Anonymous','anonymous-workspace','fixture@example.invalid','NG','Africa/Lagos','No User')$$,'P0001','authentication_required','RPC checks the current authenticated actor');
select * from finish();
rollback;
